          "tour.team.heading": "Invita\u0020il\u0020tuo\u0020team",
          "tour.template.body": "Esplora\u0020design\u0020pronti\u0020all\u2019uso\u0020per\u0020settore\u0020e\u0020stile.\u0020Ognuno\u0020pu\u00f2\u0020essere\u0020adattato\u0020al\u0020tuo\u0020brand.",
          "tour.template.heading": "Scegli\u0020un\u0020design\u0020che\u0020ti\u0020piace",
          "tour.undo.body": "Una\u0020modifica\u0020non\u0020ti\u0020piace?\u0020Annulla\u0020ripristina\u0020esattamente\u0020lo\u0020stato\u0020precedente.",
          "tour.undo.heading": "Ogni\u0020modifica\u0020pu\u00f2\u0020essere\u0020annullata",
          "tour.welcome.ask": "Chiedi",
          "tour.welcome.askBody": "\"Accorcia\u0020il\u0020titolo\"",
          "tour.welcome.body": "Tracy\u0020modifica\u0020il\u0020tuo\u0020sito\u0020web\u0020per\u0020te.\u0020Descrivi\u0020ci\u00f2\u0020che\u0020vuoi\u0020con\u0020parole\u0020semplici,\u0020controlla\u0020il\u0020risultato\u0020e\u0020pubblica\u0020quando\u0020sei\u0020soddisfatto.",
          "tour.welcome.publish": "Pubblica",
          "tour.welcome.publishBody": "Online\u0020quando\u0020lo\u0020decidi\u0020tu",
          "tour.welcome.review": "Controlla",
          "tour.welcome.reviewBody": "Guardalo\u0020prima\u0020sul\u0020tuo\u0020site",
          "tour.welcome.title": "Benvenuto\u0020in\u0020Tracy",
          "welcome.1.title": "Benvenuto\u0020in\u0020Tracy",
          "welcome.1.body": "Un\u0020modo\u0020pi\u00f9\u0020rapido\u0020di\u0020gestire\u0020il\u0020tuo\u0020sito\u0020web\u0020sul\u0020CMS\u0020di\u0020cui\u0020gi\u00e0\u0020ti\u0020fidi.\u0020Fai\u0020clic\u0020su\u0020qualsiasi\u0020parte\u0020di\u0020una\u0020pagina,\u0020chiedi\u0020la\u0020modifica,\u0020fatto.\u0020Senza\u0020aprire\u0020l\u2019admin\u0020di\u0020Joomla\u0020o\u0020WordPress.",
          "welcome.2.title": "Porta\u0020il\u0020site\u0020che\u0020hai\u0020gi\u00e0",
          "welcome.2.body": "Incolla\u0020il\u0020tuo\u0020indirizzo\u0020e\u0020Tracy\u0020crea\u0020una\u0020copia\u0020di\u0020lavoro.\u0020Il\u0020tuo\u0020site\u0020online\u0020continua\u0020a\u0020funzionare\u0020mentre\u0020modifichi,\u0020e\u0020invii\u0020le\u0020modifiche\u0020quando\u0020sei\u0020pronto.\u0020Nessuna\u0020modalit\u00e0\u0020manutenzione.",
          "welcome.3.title": "Parti\u0020da\u0020template\u0020gratuiti",
          "welcome.3.body": "Non\u0020hai\u0020ancora\u0020un\u0020site?\u0020Sfoglia\u0020un\u2019ampia\u0020libreria\u0020di\u0020template\u0020gratuiti\u0020per\u0020ogni\u0020tipo\u0020di\u0020attivit\u00e0.\u0020Guarda\u0020il\u0020preview\u0020di\u0020ciascuno\u0020in\u0020chiaro,\u0020in\u0020scuro\u0020o\u0020su\u0020smartphone,\u0020poi\u0020crea\u0020da\u0020l\u00ec\u0020il\u0020tuo\u0020site.",
          "welcome.4.title": "Un\u0020nuovo\u0020look\u0020tra\u00201200+\u0020stili",
          "welcome.4.body": "Sfoglia\u0020oltre\u00201200\u0020design\u0020system\u0020ispirati\u0020a\u0020prodotti\u0020come\u0020Figma\u0020o\u0020ElevenLabs.\u0020Scegline\u0020uno\u0020e\u0020Tracy\u0020ridisegna\u0020ogni\u0020pagina\u0020con\u0020i\u0020suoi\u0020colori,\u0020font\u0020e\u0020spaziature.",
          "welcome.5.title": "Dal\u0020tuo\u0020brief\u0020a\u0020un\u0020site",
          "welcome.5.body": "Indica\u0020a\u0020Tracy\u0020il\u0020nome\u0020della\u0020tua\u0020attivit\u00e0,\u0020cosa\u0020fai,\u0020la\u0020lingua,\u0020il\u0020tono\u0020e\u0020il\u0020tuo\u0020logo.\u0020Tracy\u0020scrive\u0020ogni\u0020pagina\u0020e\u0020crea\u0020immagini\u0020coordinate:\u0020un\u0020site\u0020quasi\u0020finito,\u0020non\u0020una\u0020demo\u0020da\u0020compilare\u0020riga\u0020per\u0020riga.",
          "welcome.6.title": "Invita\u0020il\u0020tuo\u0020team,\u0020imposta\u0020gli\u0020accessi",
          "welcome.6.body": "Invita\u0020persone\u0020nel\u0020site\u0020e\u0020assegna\u0020a\u0020ognuna\u0020un\u0020ruolo:\u0020Editor\u0020per\u0020modificare,\u0020Visualizzatore\u0020per\u0020guardare\u0020e\u0020seguire.\u0020Fai\u0020clic\u0020su\u0020qualsiasi\u0020parte\u0020di\u0020una\u0020pagina\u0020per\u0020lasciare\u0020una\u0020nota\u0020e\u0020menzionale\u0020con\u0020@.",
          "welcome.7.title": "Vedi\u0020e\u0020annulla\u0020ogni\u0020modifica",
          "welcome.7.body": "Ogni\u0020modifica\u0020viene\u0020salvata\u0020in\u0020Modifiche\u0020al\u0020site\u0020con\u0020chi\u0020l\u2019ha\u0020fatta\u0020e\u0020quando.\u0020Aprine\u0020una\u0020per\u0020vedere\u0020cosa\u0020\u00e8\u0020cambiato,\u0020oppure\u0020riporta\u0020l\u2019intero\u0020site\u0020a\u0020una\u0020versione\u0020precedente.",
          "welcome.8.title": "Vai\u0020online\u0020a\u0020modo\u0020tuo",
          "welcome.8.body": "Metti\u0020online\u0020il\u0020tuo\u0020site\u0020su\u0020Tracy\u0020con\u0020un\u0020clic\u0020e\u0020aggiungi\u0020il\u0020tuo\u0020domain.\u0020Hai\u0020importato\u0020un\u0020site?\u0020Rimanda\u0020le\u0020modifiche\u0020al\u0020tuo\u0020hosting\u0020attuale.\u0020Oppure\u0020fai\u0020il\u0020download\u0020di\u0020uno\u0020ZIP\u0020per\u0020ospitarlo\u0020dove\u0020vuoi.",
          "welcome.cta": "Crea\u0020il\u0020tuo\u0020primo\u0020site",
