          "tour.undo.body": "Niet\u0020tevreden\u0020met\u0020een\u0020wijziging?\u0020Ongedaan\u0020maken\u0020zet\u0020alles\u0020precies\u0020terug\u0020zoals\u0020het\u0020was.",
          "tour.undo.heading": "Elke\u0020wijziging\u0020kan\u0020ongedaan\u0020worden\u0020gemaakt",
          "tour.welcome.ask": "Vragen",
          "tour.welcome.askBody": "\"Maak\u0020de\u0020kop\u0020korter\"",
          "tour.welcome.body": "Tracy\u0020bewerkt\u0020je\u0020website\u0020voor\u0020je.\u0020Beschrijf\u0020je\u0020wens\u0020in\u0020gewone\u0020woorden,\u0020controleer\u0020het\u0020resultaat\u0020en\u0020publiceer\u0020wanneer\u0020je\u0020tevreden\u0020bent.",
          "tour.welcome.publish": "Publiceren",
          "tour.welcome.publishBody": "Live\u0020wanneer\u0020jij\u0020het\u0020zegt",
          "tour.welcome.review": "Controleren",
          "tour.welcome.reviewBody": "Bekijk\u0020het\u0020eerst\u0020op\u0020je\u0020site",
          "tour.welcome.title": "Welkom\u0020bij\u0020Tracy",
          "welcome.1.title": "Welkom\u0020bij\u0020Tracy",
          "welcome.1.body": "Een\u0020snellere\u0020manier\u0020om\u0020je\u0020website\u0020te\u0020beheren\u0020op\u0020het\u0020CMS\u0020dat\u0020je\u0020al\u0020vertrouwt.\u0020Klik\u0020op\u0020een\u0020deel\u0020van\u0020een\u0020pagina,\u0020vraag\u0020om\u0020de\u0020wijziging,\u0020klaar.\u0020Zonder\u0020de\u0020admin\u0020van\u0020Joomla\u0020of\u0020WordPress\u0020te\u0020openen.",
          "welcome.2.title": "Breng\u0020je\u0020bestaande\u0020site\u0020mee",
          "welcome.2.body": "Plak\u0020je\u0020adres\u0020en\u0020Tracy\u0020maakt\u0020een\u0020werkkopie.\u0020Je\u0020live\u0020site\u0020blijft\u0020draaien\u0020terwijl\u0020je\u0020bewerkt,\u0020en\u0020je\u0020stuurt\u0020de\u0020wijzigingen\u0020door\u0020zodra\u0020je\u0020er\u0020klaar\u0020voor\u0020bent.\u0020Geen\u0020onderhoudsmodus.",
          "welcome.3.title": "Begin\u0020met\u0020gratis\u0020templates",
          "welcome.3.body": "Nog\u0020geen\u0020site?\u0020Blader\u0020door\u0020een\u0020grote\u0020bibliotheek\u0020met\u0020gratis\u0020templates\u0020voor\u0020elk\u0020soort\u0020bedrijf.\u0020Bekijk\u0020de\u0020preview\u0020van\u0020elk\u0020template\u0020in\u0020licht,\u0020donker\u0020of\u0020op\u0020een\u0020telefoon\u0020en\u0020bouw\u0020er\u0020daarna\u0020je\u0020site\u0020mee.",
          "welcome.4.title": "Een\u0020nieuwe\u0020look\u0020uit\u00201.200+\u0020stijlen",
          "welcome.4.body": "Blader\u0020door\u0020meer\u0020dan\u00201.200\u0020designsystemen,\u0020ge\u00efnspireerd\u0020op\u0020producten\u0020als\u0020Figma\u0020of\u0020ElevenLabs.\u0020Kies\u0020er\u0020een\u0020en\u0020Tracy\u0020geeft\u0020elke\u0020pagina\u0020een\u0020nieuwe\u0020stijl\u0020met\u0020de\u0020kleuren,\u0020lettertypen\u0020en\u0020witruimte\u0020ervan.",
          "welcome.5.title": "Van\u0020briefing\u0020naar\u0020site",
          "welcome.5.body": "Vertel\u0020Tracy\u0020je\u0020bedrijfsnaam,\u0020wat\u0020je\u0020doet,\u0020de\u0020taal,\u0020de\u0020toon\u0020en\u0020je\u0020logo.\u0020Tracy\u0020schrijft\u0020elke\u0020pagina\u0020en\u0020maakt\u0020passende\u0020afbeeldingen:\u0020een\u0020bijna\u0020afgeronde\u0020site,\u0020geen\u0020demo\u0020om\u0020regel\u0020voor\u0020regel\u0020in\u0020te\u0020vullen.",
          "welcome.6.title": "Nodig\u0020je\u0020team\u0020uit,\u0020bepaal\u0020hun\u0020toegang",
          "welcome.6.body": "Nodig\u0020mensen\u0020uit\u0020voor\u0020de\u0020site\u0020en\u0020geef\u0020ieder\u0020een\u0020rol:\u0020Bewerker\u0020om\u0020te\u0020wijzigen,\u0020Lezer\u0020om\u0020mee\u0020te\u0020kijken.\u0020Klik\u0020op\u0020een\u0020deel\u0020van\u0020een\u0020pagina\u0020om\u0020een\u0020notitie\u0020achter\u0020te\u0020laten\u0020en\u0020tag\u0020ze\u0020met\u0020@.",
          "welcome.7.title": "Bekijk\u0020en\u0020herstel\u0020elke\u0020wijziging",
          "welcome.7.body": "Elke\u0020wijziging\u0020wordt\u0020opgeslagen\u0020in\u0020Site-wijzigingen,\u0020met\u0020wie\u0020hem\u0020maakte\u0020en\u0020wanneer.\u0020Open\u0020er\u0020een\u0020om\u0020te\u0020zien\u0020wat\u0020er\u0020veranderde,\u0020of\u0020zet\u0020de\u0020hele\u0020site\u0020terug\u0020naar\u0020een\u0020eerdere\u0020versie.",
          "welcome.8.title": "Ga\u0020live\u0020op\u0020jouw\u0020manier",
          "welcome.8.body": "Zet\u0020je\u0020site\u0020met\u0020\u00e9\u00e9n\u0020klik\u0020live\u0020op\u0020Tracy\u0020en\u0020voeg\u0020je\u0020eigen\u0020domain\u0020toe.\u0020Een\u0020site\u0020ge\u00efmporteerd?\u0020Stuur\u0020de\u0020wijzigingen\u0020terug\u0020naar\u0020je\u0020huidige\u0020hosting.\u0020Of\u0020gebruik\u0020de\u0020download\u0020als\u0020ZIP\u0020om\u0020hem\u0020overal\u0020te\u0020hosten.",
          "welcome.cta": "Bouw\u0020je\u0020eerste\u0020site",
          "welcome.close": "Welkom\u0020sluiten",
          "welcome.previous": "Vorig\u0020scherm",
