          "tour.welcome.review": "\u68c0\u67e5",
          "tour.welcome.reviewBody": "\u5148\u5728\u4f60\u7684\u0020site\u0020\u4e0a\u67e5\u770b\u6548\u679c",
          "tour.welcome.title": "\u6b22\u8fce\u4f7f\u7528\u0020Tracy",
          "welcome.1.title": "\u6b22\u8fce\u4f7f\u7528\u0020Tracy",
          "welcome.1.body": "\u5728\u4f60\u4fe1\u8d56\u7684\u0020CMS\u0020\u4e0a\u66f4\u5feb\u5730\u6253\u7406\u7f51\u7ad9\u3002\u70b9\u51fb\u9875\u9762\u7684\u4efb\u610f\u90e8\u5206\uff0c\u8bf4\u51fa\u60f3\u8981\u7684\u4fee\u6539\uff0c\u5c31\u5b8c\u6210\u4e86\u3002\u65e0\u9700\u6253\u5f00\u0020Joomla\u0020\u6216\u0020WordPress\u0020\u7684\u0020admin\u0020\u540e\u53f0\u3002",
          "welcome.2.title": "\u5e26\u4e0a\u4f60\u73b0\u6709\u7684\u0020site",
          "welcome.2.body": "\u7c98\u8d34\u4f60\u7684\u5730\u5740\uff0cTracy\u0020\u4f1a\u521b\u5efa\u4e00\u4e2a\u5de5\u4f5c\u526f\u672c\u3002\u7f16\u8f91\u671f\u95f4\uff0c\u7ebf\u4e0a\u0020site\u0020\u7167\u5e38\u8fd0\u884c\uff0c\u51c6\u5907\u597d\u540e\u518d\u628a\u4fee\u6539\u540c\u6b65\u8fc7\u53bb\u3002\u65e0\u9700\u5f00\u542f\u7ef4\u62a4\u6a21\u5f0f\u3002",
          "welcome.3.title": "\u4ece\u514d\u8d39\u0020template\u0020\u5f00\u59cb",
          "welcome.3.body": "\u8fd8\u6ca1\u6709\u0020site\uff1f\u6d4f\u89c8\u6d77\u91cf\u514d\u8d39\u0020template\uff0c\u8986\u76d6\u5404\u7c7b\u4e1a\u52a1\u3002\u53ef\u5728\u6d45\u8272\u3001\u6df1\u8272\u6216\u624b\u673a\u89c6\u56fe\u4e2d\u0020preview\u0020\u4efb\u610f\u4e00\u4e2a\uff0c\u518d\u4ee5\u5b83\u4e3a\u57fa\u7840\u642d\u5efa\u4f60\u7684\u0020site\u3002",
          "welcome.4.title": "\u4ece\u00201,200+\u0020\u79cd\u98ce\u683c\u4e2d\u7115\u65b0\u8bbe\u8ba1",
          "welcome.4.body": "\u6d4f\u89c8\u00201,200\u0020\u591a\u4e2a\u8bbe\u8ba1\u7cfb\u7edf\uff0c\u7075\u611f\u6765\u81ea\u0020Figma\u3001ElevenLabs\u0020\u7b49\u4ea7\u54c1\u3002\u9009\u5b9a\u4e00\u4e2a\uff0cTracy\u0020\u5c31\u4f1a\u7528\u5b83\u7684\u989c\u8272\u3001\u5b57\u4f53\u548c\u95f4\u8ddd\u91cd\u65b0\u8bbe\u8ba1\u6bcf\u4e2a\u9875\u9762\u3002",
          "welcome.5.title": "\u628a\u4f60\u7684\u9700\u6c42\u53d8\u6210\u0020site",
          "welcome.5.body": "\u544a\u8bc9\u0020Tracy\u0020\u4f60\u7684\u4f01\u4e1a\u540d\u79f0\u3001\u4e1a\u52a1\u5185\u5bb9\u3001\u8bed\u8a00\u3001\u8bed\u6c14\u548c\u0020logo\u3002Tracy\u0020\u4f1a\u64b0\u5199\u6bcf\u4e2a\u9875\u9762\u5e76\u751f\u6210\u5339\u914d\u7684\u56fe\u7247\uff0c\u8ba9\u4f60\u5f97\u5230\u4e00\u4e2a\u51e0\u4e4e\u5b8c\u6210\u7684\u0020site\uff0c\u800c\u4e0d\u662f\u9700\u8981\u9010\u884c\u586b\u5199\u7684\u6f14\u793a\u3002",
          "welcome.6.title": "\u9080\u8bf7\u56e2\u961f\uff0c\u8bbe\u7f6e\u6743\u9650",
          "welcome.6.body": "\u9080\u8bf7\u6210\u5458\u52a0\u5165\u0020site\uff0c\u5e76\u4e3a\u6bcf\u4eba\u5206\u914d\u89d2\u8272\uff1a\u7f16\u8f91\u8005\u8d1f\u8d23\u4fee\u6539\uff0c\u67e5\u770b\u8005\u53ef\u6d4f\u89c8\u548c\u8ddf\u8fdb\u3002\u70b9\u51fb\u9875\u9762\u7684\u4efb\u610f\u90e8\u5206\u5373\u53ef\u7559\u4e0b\u5907\u6ce8\uff0c\u5e76\u7528\u0020@\u0020\u63d0\u53ca\u4ed6\u4eec\u3002",
          "welcome.7.title": "\u67e5\u770b\u5e76\u64a4\u9500\u6bcf\u4e00\u6b21\u66f4\u6539",
          "welcome.7.body": "\u6bcf\u6b21\u66f4\u6539\u90fd\u4f1a\u4fdd\u5b58\u5728\u0020Site\u0020\u66f4\u6539\u4e2d\uff0c\u8bb0\u5f55\u64cd\u4f5c\u4eba\u548c\u65f6\u95f4\u3002\u6253\u5f00\u4efb\u4e00\u66f4\u6539\u5373\u53ef\u67e5\u770b\u6539\u52a8\u5185\u5bb9\uff0c\u6216\u5c06\u6574\u4e2a\u0020site\u0020\u56de\u9000\u5230\u66f4\u65e9\u7684\u7248\u672c\u3002",
